    const fn = FN[Math.floor(rnd()*FN.length)], to = chan==='sms' ? '+1 '+(200+Math.floor(rnd()*700))+' 555 0'+String(100+Math.floor(rnd()*899)) : chan==='webhook' ? 'https://hooks.acme.com/valasys' : fn+(rnd()<0.4?'.'+['lee','patel','garcia','kim','ng'][Math.floor(rnd()*5)]:'')+'@'+DOM[Math.floor(rnd()*DOM.length)];
