    if(rnd()<0.09) add('clicked', 300+rnd()*9000, 'acme.com/'+m.src.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,22));
    if(rnd()<0.0035) add('unsubscribed', 4000, 'One-click List-Unsubscribe (RFC 8058)');
