    if(!this._lgT) this._lgT = setInterval(()=>{ try{ if(this.state.lgLive !== false) this.lgTick(); else if(this.state.view==='logs'){ this.lgTick(); } }catch(e){} }, 2600);
    const win = st.lgWin || '24h', winMs = {'15m':9e5,'1h':36e5,'24h':864e5,'7d':6048e5}[win];
    const freeze = live ? null : (st.lgFreeze || now);
    const f = st.lgF || 'all', src = st.lgSrc || 'all';
    const raw = (st.lgQ||'').trim().toLowerCase(), toks = raw.split(/\s+/).filter(Boolean), Q = {free:[]};
    toks.forEach(t=>{ const m = t.match(/^(to|status|event|campaign|source|id|chan|channel):(.+)$/); if(m) Q[{event:'status',source:'campaign',channel:'chan'}[m[1]]||m[1]] = m[2]; else Q.free.push(t); });
    const inWin = D.all.filter(e=>e.type!=='processed' && now-e.t.getTime() <= winMs);
    const visible = freeze ? inWin.filter(e=>e.t.getTime()<=freeze) : inWin;
    const newCount = freeze ? inWin.length - visible.length : 0;
    const match = (e)=> (src==='all' || (src==='sms' ? e.m.chan==='sms' : src==='webhook' ? e.m.chan==='webhook' : e.m.kind===src && e.m.chan==='email'))
      && (!Q.to || e.m.to.toLowerCase().includes(Q.to)) && (!Q.id || e.m.id.includes(Q.id)) && (!Q.chan || e.m.chan.startsWith(Q.chan))
      && (!Q.status || e.type.startsWith(Q.status) || this.LGE[e.type][0].toLowerCase().startsWith(Q.status)) && (!Q.campaign || e.m.src.toLowerCase().includes(Q.campaign.replace(/-/g,' ')))
      && Q.free.every(w=>(e.type+' '+e.m.to+' '+e.m.id+' '+e.m.src+' '+(e.resp||'')).toLowerCase().includes(w));
    const base = visible.filter(match), filtered = f==='all' ? base : base.filter(e=>e.type===f);
